import React, { useState, useMemo } from 'react';
import { calculateEMI } from '../utils/finance';
import { useTrackCalculation } from '../hooks/useTrackCalculation';
import { Share2, IndianRupee, Calendar, Percent, CheckCircle, PercentIcon, Download } from 'lucide-react';
import { generatePDFReport } from '../utils/pdfGenerator';

export default function PersonalLoan() {
  const [amount, setAmount] = useState<number>(300000);
  const [rate, setRate] = useState<number>(12.5);
  const [tenure, setTenure] = useState<number>(5);
  const [processingFee, setProcessingFee] = useState<number>(2); // 2% processing fee
  const [shared, setShared] = useState<boolean>(false);
  const [scheduleView, setScheduleView] = useState<'monthly' | 'yearly'>('monthly');

  useTrackCalculation('personal-loan', { amount, rate, tenure, processingFee });

  const emiData = useMemo(() => {
    return calculateEMI(amount, rate, tenure);
  }, [amount, rate, tenure]);

  const feeAmount = (amount * processingFee) / 100;
  const netDisbursal = amount - feeAmount;

  const handleShare = () => {
    const text = `ClearFinCalc Personal Loan Calculation:\nAmount: ₹${amount.toLocaleString('en-IN')}\nEMI: ₹${emiData.monthlyPayment.toLocaleString('en-IN')}/mo\nRate: ${rate}%\nDisbursed Amount: ₹${netDisbursal.toLocaleString('en-IN')}\nCalculate yours at ClearFinCalc!`;
    navigator.clipboard.writeText(text);
    setShared(true);
    setTimeout(() => setShared(false), 2000);
  };

  const handleDownloadPDF = () => {
    const reportData = {
      title: 'Personal Loan Report',
      filename: 'personal-loan-report.pdf',
      summary: { label: 'Estimated Monthly EMI', value: `₹${emiData.monthlyPayment.toLocaleString('en-IN')}` },
      inputs: [
        { label: 'Loan Amount', value: `₹${amount.toLocaleString('en-IN')}` },
        { label: 'Interest Rate', value: `${rate}%` },
        { label: 'Loan Tenure', value: `${tenure} Years` },
        { label: 'Processing Fee Percentage', value: `${processingFee}%` }
      ],
      results: [
        { label: 'Monthly EMI', value: `₹${emiData.monthlyPayment.toLocaleString('en-IN')}` },
        { label: 'Total Interest Payable', value: `₹${emiData.totalInterest.toLocaleString('en-IN')}` },
        { label: 'Processing Fee Amount', value: `₹${feeAmount.toLocaleString('en-IN')}` },
        { label: 'Net Disbursed Amount', value: `₹${netDisbursal.toLocaleString('en-IN')}` },
        { label: 'Total Amount Payable (Principal + Interest)', value: `₹${emiData.totalPayment.toLocaleString('en-IN')}` }
      ]
    };
    generatePDFReport(reportData);
  };

  return (
    <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md rounded-3xl p-6 md:p-8 border border-slate-200/50 dark:border-slate-800/50 shadow-xl transition-all duration-300">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
        <div>
          <h2 className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-white leading-none">Personal Loan Calculator</h2>
          <p className="text-slate-500 dark:text-slate-400 mt-2 text-sm md:text-base">Calculate unsecured personal loan EMIs, interest details, and actual net disbursal values.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <button 
            onClick={handleDownloadPDF}
            className="flex items-center gap-2 px-4 py-2 bg-indigo-50 hover:bg-indigo-100 dark:bg-indigo-950/40 dark:hover:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 font-semibold rounded-xl text-sm transition-all border border-indigo-200/20 shadow-sm"
          >
            <Download className="w-4 h-4" aria-hidden="true" />
            PDF Report
          </button>
          <button 
            onClick={handleShare}
            className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 font-semibold rounded-xl text-sm transition-all shadow-sm"
          >
            {shared ? <CheckCircle className="w-4 h-4 text-emerald-500 animate-scale" aria-hidden="true" /> : <Share2 className="w-4 h-4" aria-hidden="true" />}
            {shared ? 'Copied!' : 'Share Result'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Left Side: Inputs */}
        <div className="lg:col-span-6 space-y-6">
          {/* Amount slider */}
          <div className="space-y-2">
            <div className="flex justify-between items-center">
              <label htmlFor="personal-loan-amount" className="text-sm font-semibold text-slate-700 dark:text-slate-300 flex items-center gap-1.5">
                <IndianRupee className="w-4 h-4 text-sky-500" aria-hidden="true" />
                Loan Amount
              </label>
              <input 
                id="personal-loan-amount"
                type="number"
                value={amount}
                onChange={(e) => setAmount(Number(e.target.value))}
                className="w-28 py-1 px-2 text-right font-bold text-slate-900 dark:text-white bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:outline-none"
              />
            </div>
            <input 
              id="personal-loan-amount-range"
              type="range"
              min="50000"
              max="2500000"
              step="10000"
              value={amount}
              onChange={(e) => setAmount(Number(e.target.value))}
              aria-label="Personal Loan Amount slider"
              className="w-full h-2 bg-slate-200 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-sky-500"
            />
            <div className="flex justify-between text-[10px] text-slate-400 font-bold">
              <span>₹50,000</span>
              <span>₹25 Lakhs</span>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {/* Interest Rate */}
            <div className="space-y-2">
              <label htmlFor="personal-loan-rate" className="text-xs font-semibold text-slate-500 dark:text-slate-400 flex items-center gap-1.5">
                <Percent className="w-3.5 h-3.5 text-emerald-500" aria-hidden="true" />
                Rate (p.a)
              </label>
              <input 
                id="personal-loan-rate"
                type="number"
                step="0.1"
                value={rate}
                onChange={(e) => setRate(Number(e.target.value))}
                className="w-full py-2 px-3 font-bold text-slate-900 dark:text-white bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none text-sm"
              />
            </div>

            {/* Tenure */}
            <div className="space-y-2">
              <label htmlFor="personal-loan-tenure" className="text-xs font-semibold text-slate-500 dark:text-slate-400 flex items-center gap-1.5">
                <Calendar className="w-3.5 h-3.5 text-indigo-500" aria-hidden="true" />
                Tenure (Yrs)
              </label>
              <input 
                id="personal-loan-tenure"
                type="number"
                value={tenure}
                onChange={(e) => setTenure(Number(e.target.value))}
                className="w-full py-2 px-3 font-bold text-slate-900 dark:text-white bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none text-sm"
              />
            </div>
          </div>

          {/* Processing Fee Input */}
          <div className="space-y-2 pt-2">
            <div className="flex justify-between items-center text-xs text-slate-500 dark:text-slate-400">
              <span className="flex items-center gap-1">
                <PercentIcon className="w-3.5 h-3.5 text-indigo-400" aria-hidden="true" />
                Processing Fees
              </span>
              <span className="font-bold text-slate-700 dark:text-slate-300">{processingFee}%</span>
            </div>
            <input 
              id="personal-loan-fee-range"
              type="range"
              min="0.5"
              max="5"
              step="0.5"
              value={processingFee}
              onChange={(e) => setProcessingFee(Number(e.target.value))}
              aria-label="Processing Fees slider"
              className="w-full h-1.5 bg-slate-200 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500"
            />
          </div>
        </div>

        {/* Right Side: Results & Disbursal details */}
        <div className="lg:col-span-6 flex flex-col justify-between space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="p-4 bg-sky-50 dark:bg-sky-950/20 border border-sky-100 dark:border-sky-900/30 rounded-2xl text-center">
              <span className="text-xs font-bold text-sky-600 dark:text-sky-400 block mb-1">Monthly EMI</span>
              <span className="text-xl font-extrabold text-sky-950 dark:text-sky-200">
                ₹{emiData.monthlyPayment.toLocaleString('en-IN')}
              </span>
            </div>

            <div className="p-4 bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-100 dark:border-emerald-900/30 rounded-2xl text-center">
              <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 block mb-1">Total Interest</span>
              <span className="text-xl font-extrabold text-emerald-950 dark:text-emerald-200">
                ₹{emiData.totalInterest.toLocaleString('en-IN')}
              </span>
            </div>
          </div>

          <div className="p-5 bg-slate-50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl space-y-3">
            <div className="flex justify-between text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">
              <span>Cost Breakup</span>
              <span>Amount</span>
            </div>
            <div className="border-t border-slate-200/50 dark:border-slate-700/50 my-1"></div>
            <div className="flex justify-between text-sm">
              <span className="text-slate-500 dark:text-slate-400">Sanctioned Amount</span>
              <span className="font-semibold text-slate-800 dark:text-slate-200">₹{amount.toLocaleString('en-IN')}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-slate-500 dark:text-slate-400">Processing Fees ({processingFee}%)</span>
              <span className="font-semibold text-rose-500">-₹{feeAmount.toLocaleString('en-IN')}</span>
            </div>
            <div className="border-t border-slate-200/50 dark:border-slate-700/50 my-1"></div>
            <div className="flex justify-between text-sm font-bold">
              <span className="text-slate-900 dark:text-white">Actual Disbursed (In Hand)</span>
              <span className="text-emerald-500">₹{netDisbursal.toLocaleString('en-IN')}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Amortization Table with Monthly/Yearly Toggle */}
      <div className="mt-8 border-t border-slate-100 dark:border-slate-800 pt-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 mb-4">
          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200">Breakup Schedule</h3>
          <div className="flex bg-slate-100 dark:bg-slate-800 rounded-xl p-1 text-xs font-bold">
            <button
              onClick={() => setScheduleView('monthly')}
              className={`px-4 py-1.5 rounded-lg transition-all ${scheduleView === 'monthly' ? 'bg-white dark:bg-slate-700 text-sky-600 dark:text-sky-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
            >
              Monthly
            </button>
            <button
              onClick={() => setScheduleView('yearly')}
              className={`px-4 py-1.5 rounded-lg transition-all ${scheduleView === 'yearly' ? 'bg-white dark:bg-slate-700 text-sky-600 dark:text-sky-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
            >
              Yearly
            </button>
          </div>
        </div>
        <div className="overflow-x-auto max-h-96 overflow-y-auto border border-slate-100 dark:border-slate-800 rounded-2xl">
          <table className="w-full text-left text-xs md:text-sm">
            <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-600 dark:text-slate-300 font-bold sticky top-0">
              <tr>
                <th className="p-3">{scheduleView === 'monthly' ? 'Month' : 'Year'}</th>
                {scheduleView === 'monthly' && <th className="p-3">EMI</th>}
                <th className="p-3">Principal Paid</th>
                <th className="p-3">Interest Paid</th>
                <th className="p-3">Remaining Balance</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800 text-slate-700 dark:text-slate-300">
              {scheduleView === 'monthly'
                ? emiData.monthlyAmortization.map((row) => (
                    <tr key={row.month} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20">
                      <td className="p-3 font-semibold">{row.month}</td>
                      <td className="p-3">₹{row.emi.toLocaleString('en-IN')}</td>
                      <td className="p-3">₹{row.principalPaid.toLocaleString('en-IN')}</td>
                      <td className="p-3">₹{row.interestPaid.toLocaleString('en-IN')}</td>
                      <td className="p-3">₹{row.remainingBalance.toLocaleString('en-IN')}</td>
                    </tr>
                  ))
                : emiData.amortization.map((row) => (
                    <tr key={row.year} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20">
                      <td className="p-3 font-semibold">Year {row.year}</td>
                      <td className="p-3">₹{row.principalPaid.toLocaleString('en-IN')}</td>
                      <td className="p-3">₹{row.interestPaid.toLocaleString('en-IN')}</td>
                      <td className="p-3">₹{row.remainingBalance.toLocaleString('en-IN')}</td>
                    </tr>
                  ))
              }
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
